/*
=========================================================
Victron Parallel VE.Bus Balance Monitor
Automatic Unit and Phase Detection
Venus OS Node-RED Function
=========================================================

PURPOSE
-------
Monitors individual VE.Bus inverter/charger power values
and calculates how evenly parallel units are sharing load.

The function automatically discovers:

- VRM Portal ID
- VE.Bus device instance
- VE.Bus device numbers
- Total number of VE.Bus units
- Number of phases
- Number of units per phase

No VRM Portal ID, phase count or unit count needs to be
entered manually.


MQTT INPUT
----------
Recommended MQTT subscription:

N/+/vebus/+/Devices/+/Ac/+/P

Expected topics:

N/<portal>/vebus/<instance>/Devices/<device>/Ac/In/P
N/<portal>/vebus/<instance>/Devices/<device>/Ac/Out/P

Typical payload:

{"value": 1234}

or:

1234


TIMER INPUT
-----------
A periodic Inject node may send:

msg.topic = "parallel-balance-tick"

Recommended interval:

30 seconds

This lets the function refresh stale-reading status even
when MQTT values have not changed.


OUTPUT
------
msg.payload = {
    detected: {
        portalId,
        vebusInstance,
        phases,
        totalUnits,
        unitsPerPhase,
        deviceNumbers,
        discoveryComplete,
        detectionReason
    },
    unitNumbers,
    out,
    in,
    updated
}


AUTOMATIC PHASE DETECTION
-------------------------
The MQTT device-power topics do not explicitly state the
phase belonging to each VE.Bus device.

The function uses the normal Victron interleaved ordering:

Three-phase example with 15 devices:

L1 = 0, 3, 6, 9, 12
L2 = 1, 4, 7, 10, 13
L3 = 2, 5, 8, 11, 14

A system is detected as three-phase when:

- Devices 0, 1 and 2 have been seen
- The detected device count is divisible by 3
- Device numbering is contiguous from 0

Otherwise, the function uses one phase.


IMPORTANT LIMITATION
--------------------
A single-phase installation containing 3, 6, 9, 12, etc.
parallel units can look identical to a three-phase system
when only these MQTT topics are available.

AUTO_PHASE_MODE can therefore be changed to:

"auto"    = automatically infer phase count
"single"  = force one-phase
"three"   = force three-phase

For a universal importable tool, leave it as "auto".


STATUS BADGES
-------------
Blue   = discovering devices
Green  = all expected readings current
Yellow = readings missing or stale
Red    = invalid data or configuration
Grey   = waiting for MQTT data
=========================================================
*/


// =====================================================
// SETTINGS
// =====================================================

// How long before a device reading is considered stale.
const STALE_MS = 90 * 1000;

// Ignore balance calculations below this average load.
const MIN_AVERAGE_W = 100;

// Allow this amount of time after a new device appears
// before considering discovery settled.
const DISCOVERY_SETTLE_MS = 15 * 1000;

// Remove a device from automatic discovery if no reading
// from either In or Out has been received for this long.
//
// Set to 0 to never remove discovered devices.
const DEVICE_REMOVE_MS = 10 * 60 * 1000;

// Phase detection mode:
//
// "auto"   = infer one-phase or three-phase
// "single" = force one-phase
// "three"  = force three-phase
const AUTO_PHASE_MODE = "auto";

// Require device numbering to start at zero and be
// contiguous before automatically choosing three-phase.
const REQUIRE_CONTIGUOUS_DEVICES = true;

// Node-RED debug logging.
const DEBUG = false;


// =====================================================
// DEBUG HELPER
// =====================================================

function debug(message) {
    if (DEBUG) {
        node.warn(message);
    }
}


// =====================================================
// BASIC VARIABLES
// =====================================================

const now = Date.now();
const isTick = msg.topic === "parallel-balance-tick";

let state = context.get("parallelBalanceState") || {
    readings: {
        In: {},
        Out: {}
    },

    devices: {},

    portalId: null,
    vebusInstance: null,

    firstDeviceTimestamp: null,
    lastNewDeviceTimestamp: null
};


// Protect against an older saved context structure.
if (!state.readings) {
    state.readings = {
        In: {},
        Out: {}
    };
}

if (!state.readings.In) {
    state.readings.In = {};
}

if (!state.readings.Out) {
    state.readings.Out = {};
}

if (!state.devices) {
    state.devices = {};
}


// =====================================================
// READ MQTT MESSAGE
// =====================================================

if (!isTick) {

    /*
     * Expected:
     *
     * N/<portal>/vebus/<instance>/Devices/<device>/Ac/In/P
     * N/<portal>/vebus/<instance>/Devices/<device>/Ac/Out/P
     */

    const topicMatch = String(msg.topic || "").match(
        /^N\/([^/]+)\/vebus\/(\d+)\/Devices\/(\d+)\/Ac\/(In|Out)\/P$/
    );

    if (!topicMatch) {
        node.status({
            fill: "yellow",
            shape: "ring",
            text: "Unexpected MQTT topic"
        });

        debug("Unexpected topic: " + String(msg.topic));

        return null;
    }

    const portalId = topicMatch[1];
    const vebusInstance = Number(topicMatch[2]);
    const device = Number(topicMatch[3]);
    const direction = topicMatch[4];

    let value = msg.payload;

    if (
        value !== null &&
        typeof value === "object" &&
        Object.prototype.hasOwnProperty.call(value, "value")
    ) {
        value = value.value;
    }

    value = Number(value);

    if (
        !Number.isInteger(device) ||
        device < 0 ||
        !Number.isInteger(vebusInstance) ||
        !Number.isFinite(value)
    ) {
        node.status({
            fill: "red",
            shape: "ring",
            text: "Invalid device or power value"
        });

        debug({
            error: "Invalid MQTT message",
            topic: msg.topic,
            payload: msg.payload
        });

        return null;
    }


    // -------------------------------------------------
    // Detect a different VE.Bus system
    // -------------------------------------------------

    const systemChanged =
        state.portalId !== null &&
        (
            state.portalId !== portalId ||
            state.vebusInstance !== vebusInstance
        );

    if (systemChanged) {
        debug({
            message: "VE.Bus system changed - resetting discovery",
            oldPortalId: state.portalId,
            newPortalId: portalId,
            oldInstance: state.vebusInstance,
            newInstance: vebusInstance
        });

        state = {
            readings: {
                In: {},
                Out: {}
            },

            devices: {},

            portalId,
            vebusInstance,

            firstDeviceTimestamp: null,
            lastNewDeviceTimestamp: null
        };
    }


    // -------------------------------------------------
    // Store system identification
    // -------------------------------------------------

    state.portalId = portalId;
    state.vebusInstance = vebusInstance;


    // -------------------------------------------------
    // Register discovered device
    // -------------------------------------------------

    const isNewDevice =
        !Object.prototype.hasOwnProperty.call(
            state.devices,
            device
        );

    if (isNewDevice) {
        state.devices[device] = {
            firstSeen: now,
            lastSeen: now
        };

        if (state.firstDeviceTimestamp === null) {
            state.firstDeviceTimestamp = now;
        }

        state.lastNewDeviceTimestamp = now;

        debug(
            "Discovered VE.Bus device " +
            device
        );
    } else {
        state.devices[device].lastSeen = now;
    }


    // -------------------------------------------------
    // Store power reading
    // -------------------------------------------------

    state.readings[direction][device] = {
        value,
        timestamp: now
    };
}


// =====================================================
// REMOVE DEVICES THAT HAVE DISAPPEARED
// =====================================================

if (DEVICE_REMOVE_MS > 0) {
    Object.keys(state.devices).forEach(deviceKey => {
        const device = Number(deviceKey);
        const deviceInfo = state.devices[device];

        if (
            now - deviceInfo.lastSeen >
            DEVICE_REMOVE_MS
        ) {
            delete state.devices[device];
            delete state.readings.In[device];
            delete state.readings.Out[device];

            state.lastNewDeviceTimestamp = now;

            debug(
                "Removed inactive VE.Bus device " +
                device
            );
        }
    });
}


// =====================================================
// DISCOVER DEVICE NUMBERS
// =====================================================

const deviceNumbers = Object.keys(state.devices)
    .map(Number)
    .filter(Number.isInteger)
    .sort((a, b) => a - b);

const totalUnits = deviceNumbers.length;


// =====================================================
// WAITING FOR FIRST DEVICE
// =====================================================

if (totalUnits === 0) {
    context.set("parallelBalanceState", state);

    node.status({
        fill: "grey",
        shape: "ring",
        text: "Waiting for VE.Bus MQTT data"
    });

    return null;
}


// =====================================================
// CHECK DEVICE NUMBERING
// =====================================================

const startsAtZero =
    deviceNumbers.length > 0 &&
    deviceNumbers[0] === 0;

const contiguousDevices = deviceNumbers.every(
    (device, index) => {
        return device === index;
    }
);

const containsFirstThree =
    deviceNumbers.includes(0) &&
    deviceNumbers.includes(1) &&
    deviceNumbers.includes(2);


// =====================================================
// AUTOMATIC PHASE DETECTION
// =====================================================

let phases = 1;
let detectionReason = "";

if (AUTO_PHASE_MODE === "single") {
    phases = 1;
    detectionReason =
        "Single-phase forced in settings";
} else if (AUTO_PHASE_MODE === "three") {
    phases = 3;
    detectionReason =
        "Three-phase forced in settings";
} else {
    const numberingAcceptable =
        !REQUIRE_CONTIGUOUS_DEVICES ||
        (
            startsAtZero &&
            contiguousDevices
        );

    const looksThreePhase =
        totalUnits >= 3 &&
        totalUnits % 3 === 0 &&
        containsFirstThree &&
        numberingAcceptable;

    if (looksThreePhase) {
        phases = 3;

        detectionReason =
            "Device count and numbering match " +
            "Victron three-phase ordering";
    } else {
        phases = 1;

        if (totalUnits < 3) {
            detectionReason =
                "Fewer than three devices detected";
        } else if (totalUnits % 3 !== 0) {
            detectionReason =
                "Device count is not divisible by three";
        } else if (!containsFirstThree) {
            detectionReason =
                "Devices 0, 1 and 2 not all detected";
        } else {
            detectionReason =
                "Device numbering is not contiguous";
        }
    }
}


// =====================================================
// VALIDATE DETECTED CONFIGURATION
// =====================================================

if (totalUnits % phases !== 0) {
    context.set("parallelBalanceState", state);

    node.status({
        fill: "red",
        shape: "ring",
        text:
            totalUnits +
            " units cannot be split over " +
            phases +
            " phases"
    });

    node.error(
        "Detected unit count is not divisible by " +
        "the detected phase count"
    );

    return null;
}

const unitsPerPhase = totalUnits / phases;


// =====================================================
// DISCOVERY STATUS
// =====================================================

const lastDiscoveryChange =
    state.lastNewDeviceTimestamp ||
    state.firstDeviceTimestamp ||
    now;

const discoveryComplete =
    now - lastDiscoveryChange >=
    DISCOVERY_SETTLE_MS;


// =====================================================
// FORMAT POWER VALUE
// =====================================================

function formatWatts(value) {
    return (
        Math.round(value)
            .toLocaleString("en-GB") +
        " W"
    );
}


// =====================================================
// GET DEVICES FOR A PHASE
// =====================================================

function devicesForPhase(phaseIndex) {

    if (phases === 1) {
        return [...deviceNumbers];
    }

    /*
     * Victron interleaved device ordering:
     *
     * L1 = 0, 3, 6, 9...
     * L2 = 1, 4, 7, 10...
     * L3 = 2, 5, 8, 11...
     */

    return deviceNumbers.filter(device => {
        return device % phases === phaseIndex;
    });
}


// =====================================================
// BUILD BALANCE TABLE
// =====================================================

function buildTable(direction) {

    const phaseNames =
        phases === 3
            ? ["L1", "L2", "L3"]
            : ["L1"];

    return phaseNames.map(
        (phase, phaseIndex) => {

            const phaseDevices =
                devicesForPhase(phaseIndex);

            const units = phaseDevices.map(
                (device, unitIndex) => {

                    const reading =
                        state.readings[direction][device];

                    const stale =
                        !reading ||
                        now - reading.timestamp >
                        STALE_MS;

                    return {
                        unit: unitIndex + 1,
                        device,
                        value:
                            reading
                                ? reading.value
                                : null,
                        magnitude:
                            reading
                                ? Math.abs(reading.value)
                                : null,
                        stale,
                        ageSeconds:
                            reading
                                ? Math.round(
                                    (
                                        now -
                                        reading.timestamp
                                    ) / 1000
                                )
                                : null,
                        text:
                            reading
                                ? formatWatts(
                                    reading.value
                                )
                                : "--"
                    };
                }
            );

            const current = units.filter(
                unit => !unit.stale
            );

            const expectedForPhase =
                phases === 1
                    ? totalUnits
                    : unitsPerPhase;

            const complete =
                units.length === expectedForPhase &&
                current.length === expectedForPhase;

            let average = null;
            let lowest = null;
            let highest = null;
            let spread = null;
            let balance = null;
            let averageImbalance = null;

            if (complete) {
                const magnitudes = current.map(
                    unit => unit.magnitude
                );

                average =
                    magnitudes.reduce(
                        (sum, value) => {
                            return sum + value;
                        },
                        0
                    ) / magnitudes.length;

                lowest = Math.min(...magnitudes);
                highest = Math.max(...magnitudes);
                spread = highest - lowest;

                if (
                    average >= MIN_AVERAGE_W &&
                    highest > 0
                ) {
                    /*
                     * Primary metric:
                     *
                     * 100% means the lowest and highest
                     * loaded units are identical.
                     */
                    balance =
                        lowest / highest * 100;

                    /*
                     * Secondary metric:
                     *
                     * Spread relative to phase average.
                     */
                    averageImbalance =
                        spread / average * 100;
                }
            }

            let level = "unknown";
            let balanceText = "STALE";

            if (
                complete &&
                average !== null &&
                average < MIN_AVERAGE_W
            ) {
                level = "low-load";
                balanceText = "LOW LOAD";
            } else if (balance !== null) {
                balanceText =
                    balance.toFixed(0) +
                    "% (" +
                    averageImbalance.toFixed(0) +
                    "%)";

                if (balance >= 95) {
                    level = "excellent";
                } else if (balance >= 90) {
                    level = "good";
                } else if (balance >= 80) {
                    level = "warning";
                } else if (balance >= 70) {
                    level = "poor";
                } else {
                    level = "bad";
                }
            }

            return {
                phase,
                expectedUnits: expectedForPhase,
                currentUnits: current.length,
                complete,
                units,

                average,
                lowest,
                highest,
                spread,
                balance,
                averageImbalance,

                averageText:
                    average === null
                        ? "--"
                        : formatWatts(average),

                lowestText:
                    lowest === null
                        ? "--"
                        : formatWatts(lowest),

                highestText:
                    highest === null
                        ? "--"
                        : formatWatts(highest),

                spreadText:
                    spread === null
                        ? "--"
                        : formatWatts(spread),

                balanceText,
                level
            };
        }
    );
}


// =====================================================
// CREATE INPUT AND OUTPUT TABLES
// =====================================================

const outRows = buildTable("Out");
const inRows = buildTable("In");


// =====================================================
// COUNT STALE READINGS
// =====================================================

const allUnits = [...outRows, ...inRows]
    .flatMap(row => row.units);

const staleCount = allUnits.filter(
    unit => unit.stale
).length;

const currentCount =
    allUnits.length - staleCount;


// =====================================================
// NODE STATUS
// =====================================================

if (!discoveryComplete) {
    const remainingSeconds = Math.max(
        0,
        Math.ceil(
            (
                DISCOVERY_SETTLE_MS -
                (
                    now -
                    lastDiscoveryChange
                )
            ) / 1000
        )
    );

    node.status({
        fill: "blue",
        shape: "ring",
        text:
            "Discovering: " +
            totalUnits +
            " units, " +
            phases +
            " phase" +
            (phases === 1 ? "" : "s") +
            " · " +
            remainingSeconds +
            "s"
    });
} else if (staleCount > 0) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text:
            phases +
            "φ · " +
            totalUnits +
            " units · " +
            staleCount +
            " stale"
    });
} else {
    node.status({
        fill: "green",
        shape: "dot",
        text:
            phases +
            "φ · " +
            totalUnits +
            " units · all current"
    });
}


// =====================================================
// BUILD OUTPUT
// =====================================================

msg.topic = "parallel_balance";

msg.payload = {
    detected: {
        portalId: state.portalId,
        vebusInstance: state.vebusInstance,

        phases,
        totalUnits,
        unitsPerPhase,

        deviceNumbers,
        contiguousDevices,

        discoveryComplete,
        detectionReason,
        phaseMode: AUTO_PHASE_MODE
    },

    unitNumbers: Array.from(
        {
            length: unitsPerPhase
        },
        (_, index) => index + 1
    ),

    out: outRows,
    in: inRows,

    readingSummary: {
        totalExpectedReadings:
            allUnits.length,
        currentReadings:
            currentCount,
        staleReadings:
            staleCount
    },

    updated: new Date(now).toLocaleString(
        "en-GB",
        {
            hour12: false
        }
    )
};


// =====================================================
// SAVE CONTEXT
// =====================================================

context.set(
    "parallelBalanceState",
    state
);


debug({
    detected: msg.payload.detected,
    readingSummary:
        msg.payload.readingSummary
});

return msg;

/*
=========================================================
Victron Parallel VE.Bus Load History
Individual Unit Power — Rolling 60 Minutes
Venus OS Node-RED Function
=========================================================

INPUT MQTT
----------
N/+/vebus/+/Devices/+/Ac/+/P

Examples:

N/<portal>/vebus/<instance>/Devices/0/Ac/Out/P
N/<portal>/vebus/<instance>/Devices/0/Ac/In/P

Payload:

{"value":1234}

or:

1234


OUTPUT
------
Rolling history of actual individual VE.Bus unit load.

No balance percentage is calculated for the graph.

History is sampled every 30 seconds.

Anything older than 60 minutes is automatically deleted.


PHASE ORDER
-----------
Three phase Victron ordering:

L1 = 0, 3, 6, 9, 12...
L2 = 1, 4, 7, 10, 13...
L3 = 2, 5, 8, 11, 14...


SETTINGS
--------
AUTO_PHASE_MODE:

"auto"
"single"
"three"
=========================================================
*/


// =====================================================
// SETTINGS
// =====================================================

const STALE_MS = 90 * 1000;

const DEVICE_REMOVE_MS =
    10 * 60 * 1000;

const AUTO_PHASE_MODE =
    "auto";

const REQUIRE_CONTIGUOUS_DEVICES =
    true;


// History window
const HISTORY_MS =
    60 * 60 * 1000;


// History sample interval
const HISTORY_SAMPLE_MS =
    30 * 1000;


// Debug
const DEBUG =
    false;


// =====================================================
// DEBUG
// =====================================================

function debug(data) {

    if (DEBUG) {
        node.warn(data);
    }
}


// =====================================================
// TIME
// =====================================================

const now =
    Date.now();


// =====================================================
// LOAD STATE
// =====================================================

let state =
    context.get("parallelLoadHistory") || {

        readings: {
            In: {},
            Out: {}
        },

        devices: {},

        portalId: null,

        vebusInstance: null,

        history: [],

        lastHistoryTimestamp: 0
    };


// =====================================================
// PROTECT OLD CONTEXT
// =====================================================

if (!state.readings) {

    state.readings = {
        In: {},
        Out: {}
    };
}


if (!state.readings.In) {
    state.readings.In = {};
}


if (!state.readings.Out) {
    state.readings.Out = {};
}


if (!state.devices) {
    state.devices = {};
}


if (!Array.isArray(state.history)) {
    state.history = [];
}


if (
    !Number.isFinite(
        state.lastHistoryTimestamp
    )
) {

    state.lastHistoryTimestamp =
        0;
}


// =====================================================
// MQTT INPUT
// =====================================================

const topicMatch =
    String(msg.topic || "").match(
        /^N\/([^/]+)\/vebus\/(\d+)\/Devices\/(\d+)\/Ac\/(In|Out)\/P$/
    );


if (!topicMatch) {

    node.status({

        fill: "yellow",

        shape: "ring",

        text: "Waiting for VE.Bus power data"
    });


    return null;
}


// =====================================================
// EXTRACT TOPIC DATA
// =====================================================

const portalId =
    topicMatch[1];


const vebusInstance =
    Number(topicMatch[2]);


const device =
    Number(topicMatch[3]);


const direction =
    topicMatch[4];


// =====================================================
// EXTRACT VALUE
// =====================================================

let value =
    msg.payload;


if (
    value !== null &&
    typeof value === "object" &&
    Object.prototype.hasOwnProperty.call(
        value,
        "value"
    )
) {

    value =
        value.value;
}


value =
    Number(value);


// =====================================================
// VALIDATE
// =====================================================

if (
    !Number.isInteger(device) ||
    device < 0 ||
    !Number.isInteger(vebusInstance) ||
    !Number.isFinite(value)
) {

    node.status({

        fill: "red",

        shape: "ring",

        text: "Invalid VE.Bus power data"
    });


    return null;
}


// =====================================================
// SYSTEM CHANGE
// =====================================================

const systemChanged =

    state.portalId !== null &&

    (
        state.portalId !== portalId ||

        state.vebusInstance !==
            vebusInstance
    );


if (systemChanged) {

    state = {

        readings: {
            In: {},
            Out: {}
        },

        devices: {},

        portalId,

        vebusInstance,

        history: [],

        lastHistoryTimestamp: 0
    };


    debug(
        "VE.Bus system changed - history reset"
    );
}


// =====================================================
// STORE SYSTEM
// =====================================================

state.portalId =
    portalId;


state.vebusInstance =
    vebusInstance;


// =====================================================
// REGISTER DEVICE
// =====================================================

if (!state.devices[device]) {

    state.devices[device] = {

        firstSeen: now,

        lastSeen: now
    };


    debug(
        "Detected VE.Bus device " +
        device
    );

} else {

    state.devices[device].lastSeen =
        now;
}


// =====================================================
// STORE POWER READING
// =====================================================

state.readings[direction][device] = {

    value,

    timestamp: now
};


// =====================================================
// REMOVE DISAPPEARED DEVICES
// =====================================================

if (DEVICE_REMOVE_MS > 0) {

    Object
        .keys(state.devices)
        .forEach(key => {

            const dev =
                Number(key);


            if (
                now -
                state.devices[dev].lastSeen >
                DEVICE_REMOVE_MS
            ) {

                delete state.devices[dev];

                delete state.readings.In[dev];

                delete state.readings.Out[dev];
            }
        });
}


// =====================================================
// DEVICE LIST
// =====================================================

const deviceNumbers =
    Object
        .keys(state.devices)
        .map(Number)
        .sort(
            (a, b) => a - b
        );


const totalUnits =
    deviceNumbers.length;


if (totalUnits === 0) {

    return null;
}


// =====================================================
// PHASE DETECTION
// =====================================================

const startsAtZero =
    deviceNumbers[0] === 0;


const contiguous =
    deviceNumbers.every(
        (dev, index) =>
            dev === index
    );


const containsFirstThree =

    deviceNumbers.includes(0) &&

    deviceNumbers.includes(1) &&

    deviceNumbers.includes(2);


let phases =
    1;


if (
    AUTO_PHASE_MODE === "three"
) {

    phases =
        3;


} else if (
    AUTO_PHASE_MODE === "single"
) {

    phases =
        1;


} else {

    const numberingOK =

        !REQUIRE_CONTIGUOUS_DEVICES ||

        (
            startsAtZero &&
            contiguous
        );


    if (
        totalUnits >= 3 &&
        totalUnits % 3 === 0 &&
        containsFirstThree &&
        numberingOK
    ) {

        phases =
            3;
    }
}


// =====================================================
// PHASE FOR DEVICE
// =====================================================

function phaseForDevice(dev) {

    if (phases === 1) {

        return "L1";
    }


    const index =
        dev % 3;


    if (index === 0) {
        return "L1";
    }


    if (index === 1) {
        return "L2";
    }


    return "L3";
}


// =====================================================
// REMOVE HISTORY OLDER THAN 60 MINUTES
// =====================================================

const cutoff =
    now - HISTORY_MS;


state.history =
    state.history.filter(
        sample => {

            return (
                sample &&
                Number.isFinite(
                    sample.timestamp
                ) &&
                sample.timestamp >= cutoff
            );
        }
    );


// =====================================================
// RECORD HISTORY SAMPLE
// =====================================================

const historyDue =

    now -
    state.lastHistoryTimestamp >=
    HISTORY_SAMPLE_MS;


if (historyDue) {

    const sample = {

        timestamp:
            now,

        out: {},

        in: {}
    };


    deviceNumbers.forEach(
        dev => {

            // -----------------------------------------
            // OUTPUT POWER
            // -----------------------------------------

            const outReading =
                state.readings.Out[dev];


            if (
                outReading &&
                now -
                outReading.timestamp <=
                STALE_MS
            ) {

                sample.out[dev] =
                    outReading.value;

            } else {

                sample.out[dev] =
                    null;
            }


            // -----------------------------------------
            // INPUT POWER
            // -----------------------------------------

            const inReading =
                state.readings.In[dev];


            if (
                inReading &&
                now -
                inReading.timestamp <=
                STALE_MS
            ) {

                sample.in[dev] =
                    inReading.value;

            } else {

                sample.in[dev] =
                    null;
            }
        }
    );


    state.history.push(
        sample
    );


    state.lastHistoryTimestamp =
        now;
}


// =====================================================
// DEVICE INFORMATION FOR TEMPLATE
// =====================================================

const units =
    deviceNumbers.map(
        dev => {

            return {

                device:
                    dev,

                phase:
                    phaseForDevice(dev)
            };
        }
    );


// =====================================================
// OUTPUT
// =====================================================

msg.topic =
    "parallel_load_history";


msg.payload = {

    detected: {

        portalId:
            state.portalId,

        vebusInstance:
            state.vebusInstance,

        phases,

        totalUnits,

        deviceNumbers
    },

    units,

    history:
        state.history,

    historyInfo: {

        windowMinutes:
            60,

        sampleIntervalSeconds:
            HISTORY_SAMPLE_MS / 1000,

        samples:
            state.history.length
    },

    updated:
        new Date(now)
            .toLocaleString(
                "en-GB",
                {
                    hour12: false
                }
            )
};


// =====================================================
// SAVE
// =====================================================

context.set(
    "parallelLoadHistory",
    state
);


// =====================================================
// STATUS
// =====================================================

node.status({

    fill: "green",

    shape: "dot",

    text:
        phases +
        "φ · " +
        totalUnits +
        " units · " +
        state.history.length +
        " samples"
});


return msg;
